/**  PDF à importer : pages extraites, plage, lignes et options de nettoyage. */
export type PdfSource_Deserialize = {
	/**  Nom du fichier, gardé comme origine du texte. */
	fileName: string,
	/**
	 *  Pages extraites : celles de la plage, et si possible quelques voisines,
	 *  qui aident à reconnaître les en-têtes répétés.
	 */
	pages: PdfPage[],
	/**  Pages retenues. */
	range: PageRange,
	/**  Lignes retenues parmi celles des pages ; toutes si absent. */
	lines?: LineSelection | null,
	/**  Étapes du nettoyage. */
	options?: CleanOptions_Deserialize,
};

/**  PDF à importer : pages extraites, plage, lignes et options de nettoyage. */
export type PdfSource_Serialize = {
	/**  Nom du fichier, gardé comme origine du texte. */
	fileName: string,
	/**
	 *  Pages extraites : celles de la plage, et si possible quelques voisines,
	 *  qui aident à reconnaître les en-têtes répétés.
	 */
	pages: PdfPage[],
	/**  Pages retenues. */
	range: PageRange,
	/**  Lignes retenues parmi celles des pages ; toutes si absent. */
	lines: LineSelection | null,
	/**  Étapes du nettoyage. */
	options: CleanOptions_Serialize,
};

/**  Texte importé d'un PDF, tel que validé (et éventuellement corrigé) par l'utilisateur. */
export type PdfText = PdfText_Serialize | PdfText_Deserialize;

/**  Texte importé d'un PDF, tel que validé (et éventuellement corrigé) par l'utilisateur. */
export type PdfText_Deserialize = {
	/**  Titre, obligatoire. */
	title: string,
	/**  Auteur, facultatif. */
	author?: string | null,
	/**  Étiquettes. */
	tags: string[],
	/**  Code de langue. */
	language: string,
	/**  Découpage en exercices. */
	segmentation: Segmentation,
	/**  Nom du fichier d'origine. */
	fileName: string,
	/**  Pages retenues. */
	range: PageRange,
	/**  Texte de l'aperçu, modifiable avant validation (F-22). */
	content: string,
};

/**  Texte importé d'un PDF, tel que validé (et éventuellement corrigé) par l'utilisateur. */
export type PdfText_Serialize = {
	/**  Titre, obligatoire. */
	title: string,
	/**  Auteur, facultatif. */
	author: string | null,
	/**  Étiquettes. */
	tags: string[],
	/**  Code de langue. */
	language: string,
	/**  Découpage en exercices. */
	segmentation: Segmentation,
	/**  Nom du fichier d'origine. */
	fileName: string,
	/**  Pages retenues. */
	range: PageRange,
	/**  Texte de l'aperçu, modifiable avant validation (F-22). */
	content: string,
};

/**  Session interrompue proposée à la reprise (NF-06). */
export type PendingSession = PendingSession_Serialize | PendingSession_Deserialize;

/**  Session interrompue proposée à la reprise (NF-06). */
export type PendingSession_Deserialize = {
	/**  Identifiant de la session. */
	sessionId: string,
	/**  Texte de la session : un autre texte demandé ne propose pas cette reprise. */
	textId?: string | null,
	/**  Copie ou révision. */
	mode: SessionMode,
	/**  Titre du texte ; vide pour une révision. */
	title: string,
	/**  Exercice interrompu. */
	exercise: ExerciseInfo,
	/**  Avancement dans l'exercice, de 0 à 1. */
	progress: number | null,
	/**  Début, en ms Unix. */
	startedAt: number,
};

/**  Session interrompue proposée à la reprise (NF-06). */
export type PendingSession_Serialize = {
	/**  Identifiant de la session. */
	sessionId: string,
	/**  Texte de la session : un autre texte demandé ne propose pas cette reprise. */
	textId: string | null,
	/**  Copie ou révision. */
	mode: SessionMode,
	/**  Titre du texte ; vide pour une révision. */
	title: string,
	/**  Exercice interrompu. */
	exercise: ExerciseInfo,
	/**  Avancement dans l'exercice, de 0 à 1. */
	progress: number | null,
	/**  Début, en ms Unix. */
	startedAt: number,
};

/**  Période affichée par le tableau de bord. */
export type Period = 
/**  Les 7 derniers jours, aujourd'hui compris. */
"week" | 
/**  Les 30 derniers jours, aujourd'hui compris. */
"month" | 
/**  Depuis le début. */
"all";

