/**  Forme d'exercice demandée par l'interface. */
export type ReviewExerciseKind = 
/**  Chaque mot une fois, dans un ordre mélangé. */
{ type: "shuffled" } | 
/**  Chaque mot répété `times` fois de suite. */
{ type: "repeated"; 
/**  Répétitions de chaque mot (1 à `MAX_REPEAT`). */
times: number } | 
/**  Phrases de la bibliothèque qui contiennent ces mots. */
{ type: "sentences" };

/**  Vue d'ensemble de la révision : carte de l'accueil et badge du menu (F-43). */
export type ReviewOverview = {
	/**  Mots à réviser aujourd'hui, du plus en retard au plus récent. */
	due: string[],
	/**  Mots en révision, dus ou non. */
	tracked: number,
	/**  Mots maîtrisés (automatiquement ou à la main). */
	mastered: number,
};

/**
 *  Réglages du module Révision, rangés sous la clé `review` de `profiles.settings`
 *  (ADR 0010).
 */
export type ReviewSettings = ReviewSettings_Serialize | ReviewSettings_Deserialize;

/**
 *  Réglages du module Révision, rangés sous la clé `review` de `profiles.settings`
 *  (ADR 0010).
 */
export type ReviewSettings_Deserialize = {
	/**
	 *  Un mot tapé plus de `slow_factor` fois plus lentement que la moyenne de la
	 *  session devient difficile (F-40).
	 */
	slowFactor?: number | null,
};

/**
 *  Réglages du module Révision, rangés sous la clé `review` de `profiles.settings`
 *  (ADR 0010).
 */
export type ReviewSettings_Serialize = {
	/**
	 *  Un mot tapé plus de `slow_factor` fois plus lentement que la moyenne de la
	 *  session devient difficile (F-40).
	 */
	slowFactor: number | null,
};

/**  Découpage d'un texte en exercices. */
export type Segmentation = 
/**  Un seul exercice : le texte entier. */
{ type: "whole" } | 
/**  `count` paragraphes par exercice. */
{ type: "paragraphs"; 
/**  Paragraphes par exercice. */
count: number } | 
/**  `count` lignes par exercice. */
{ type: "lines"; 
/**  Lignes par exercice. */
count: number };

/**  Type de session (F-06). */
export type SessionGoal = 
/**  Jusqu'au dernier caractère du texte. */
{ type: "wholeText" } | 
/**  Durée fixe, en minutes. */
{ type: "duration"; 
/**  Durée de la session, en minutes. */
minutes: number } | 
/**  Nombre de mots fixe. */
{ type: "words"; 
/**  Nombre de mots à taper. */
count: number };

/**
 *  Nature d'une session : copie d'un texte de la bibliothèque, ou révision sur un
 *  texte généré à partir des mots difficiles (ADR 0018).
 */
export type SessionMode = 
/**  Texte de la bibliothèque. */
"copy" | 
/**  Exercice de révision généré (F-44). */
"review";

/**  Tout ce qu'il faut à l'interface pour afficher une session. */
export type SessionStart = SessionStart_Serialize | SessionStart_Deserialize;

/**  Tout ce qu'il faut à l'interface pour afficher une session. */
export type SessionStart_Deserialize = {
	/**  Identifiant de la session. */
	sessionId: string,
	/**  Texte tapé ; `None` pour une révision. */
	textId?: string | null,
	/**  Copie ou révision. */
	mode: SessionMode,
	/**  Titre du texte ; vide pour une révision (l'interface affiche le sien). */
	title: string,
	/**  Exercice tapé (F-24). */
	exercise: ExerciseInfo,
	/**  Exercice découpé en graphèmes : les positions des deux côtés coïncident (ADR 0008). */
	graphemes: string[],
	/**  Bornes des mots, pour l'objectif « nombre de mots ». */
	words: WordSpan[],
	/**  Réglages figés pour la session. */
	settings: PracticeSettings_Deserialize,
	/**  Frappes déjà enregistrées, à rejouer (reprise) ; vide pour une nouvelle session. */
	keystrokes: Keystroke_Deserialize[],
	/**  Temps actif déjà écoulé. */
	activeMs: number,
};

/**  Tout ce qu'il faut à l'interface pour afficher une session. */
export type SessionStart_Serialize = {
	/**  Identifiant de la session. */
	sessionId: string,
	/**  Texte tapé ; `None` pour une révision. */
	textId: string | null,
	/**  Copie ou révision. */
	mode: SessionMode,
	/**  Titre du texte ; vide pour une révision (l'interface affiche le sien). */
	title: string,
	/**  Exercice tapé (F-24). */
	exercise: ExerciseInfo,
	/**  Exercice découpé en graphèmes : les positions des deux côtés coïncident (ADR 0008). */
	graphemes: string[],
	/**  Bornes des mots, pour l'objectif « nombre de mots ». */
	words: WordSpan[],
	/**  Réglages figés pour la session. */
	settings: PracticeSettings_Serialize,
	/**  Frappes déjà enregistrées, à rejouer (reprise) ; vide pour une nouvelle session. */
	keystrokes: Keystroke_Serialize[],
	/**  Temps actif déjà écoulé. */
	activeMs: number,
};

/**  Statistiques d'une session terminée (F-30). */
export type SessionStats = {
	/**  Temps actif, pauses exclues. */
	durationMs: number,
	/**  Caractères frappés (insertions, justes ou non). */
	typed: number,
	/**  Frappes fausses, corrigées ou non. */
	errors: number,
	/**  Caractères encore faux à la fin. */
	uncorrected: number,
	/**  Mots par minute bruts : toutes les frappes, justes ou non. */
	wpmRaw: number | null,
	/**  Mots par minute nets : brut moins les erreurs non corrigées. */
	wpmNet: number | null,
	/**  Caractères justes par minute. */
	cpm: number | null,
	/**  En %, de 0 à 100. */
	accuracy: number | null,
};

/**  Résumé de l'écran de fin (F-32). */
